def _run_repo_script(name: str) -> None:
    """Run `scripts/<name>.py` from the repo as `__main__`, with `scripts/` importable (they share `_bench_common`)."""
    script = _find_repo_root() / "scripts" / f"{name}.py"
    if not script.exists():
        raise FileNotFoundError(f"Script not found at {script}. Install the package from the repository (uv sync).")
    sys.path.insert(0, str(script.parent))
    sys.argv[0] = f"{name}.py"
    runpy.run_path(str(script), run_name="__main__")


